                "panelPos=(", panelX.toFixed(1), ",", panelY.toFixed(1), ")",
                "panelSize=(", panelW.toFixed(1), ",", panelH.toFixed(1), ")",
                "sizeMode=", useDesiredSize ? "desired" : "actual",
                "hA=", hAlign,
                "vA=", vAlign,
                "world=(", screenX.toFixed(1), ",", screenY.toFixed(1), ")",
                "center=(", centerX.toFixed(1), ",", centerY.toFixed(1), ")",
                "anchor=(", anchorX.toFixed(1), ",", anchorY.toFixed(1), ")",
                "dCenter=(", dx, ",", dy, ")",
                "dAnchor=(", dax, ",", day, ")");
        }
    }

    function tryResolveEntity() {
